  return key ? bwLineStyles[key] : bwLineStyles.northern
}

/** Stack height in diagram `x` units (UG 8 = 1×). */
export const monoLineHeightUnits = (layers: readonly StrokeLayer[]): number => {
  const outer = layers.reduce((max, layer) => Math.max(max, layer.width), 0)
  return outer / UG
}

const scaleDash = (dash: string, factor: number): string =>
  dash
    .split(/\s+/)
    .map((part) => String(Number(part) * factor))
    .join(" ")

/** Scale motif widths, dashes, and offsets so UG 8 maps to diagram unit `x`. */
export const scaleMonoLayers = (
  layers: readonly StrokeLayer[],
  x: number
): StrokeLayer[] => {
  const factor = x / UG
  return layers.map((layer) => ({
    ...layer,
    width: layer.width * factor,
    dash: layer.dash ? scaleDash(layer.dash, factor) : undefined,
    dashoffset:
      layer.dashoffset != null ? layer.dashoffset * factor : undefined,
  }))
}

import {
  DIAGRAM_BASELINE,
  HORIZONTAL_NAME_SIZE_UNITS,
  LINE_DIAGRAM,
  VERTICAL_NAME_SIZE_UNITS,
  horizontalStationFontSize,
  scale,
  verticalStationFontSize,
} from "@/lib/tfl/line-diagram"
import type {
  SchematicLayout,
  SchematicLayoutPoint,
  SchematicOrientation,
} from "@/lib/tfl/schematic-layout"

/**
 * Pure label placement for BranchStrip — shared by the UI and regression tests.
 *
 * After edits, verify visually at http://localhost:3999/docs/branch-strip-horizontal
 * (see checklist on `BranchStrip`).
 */

/** Station-name line-height used for label boxes and pitch multiples. */
export const BRANCH_STRIP_LABEL_LINE_HEIGHT = 1.15

/**
 * Station pitch / lane pitch as multiples of the station-name em.
 * Chosen so default `DIAGRAM_BASELINE` matches the previous `scale(x, N)` look:
 * horizontal 12x/10x with font 2x → 6em/5em; vertical 14x/20x with font ≈4.286x.
 */
const PITCH_EM = {
  horizontal: { main: 6, lane: 5, padding: 2 },
  vertical: {
    main: 14 / VERTICAL_NAME_SIZE_UNITS,
    lane: 20 / VERTICAL_NAME_SIZE_UNITS,
    padding: 6 / VERTICAL_NAME_SIZE_UNITS,
    /** Was `scale(x, 16)` — same em at vertical name size. */
    labelWidth: 16 / VERTICAL_NAME_SIZE_UNITS,
  },
} as const

export type BranchStripMetrics = {
  x: number
  orientation: SchematicOrientation
  nameFont: number
  labelLineHeight: number
  /** One line of station text: `nameFont × labelLineHeight`. */
  lineBox: number
  mainPitch: number
  lanePitch: number
  padding: number
  verticalLabelWidth: number
  labelClearance: number
  labelMaxWidth: number
  labelGap: number
  labelBandTop: number
  labelBandBottom: number
  labelSideLeft: number
  labelSideRight: number
  endPad: number
  strokeWidth: number
  tickProtrude: number
  ringOuter: number
  ringStroke: number
}

/**
 * BranchStrip layout lengths derived from diagram `x` → station font → em pitches.
 * Tests and the component must share this so geometry tracks base type size.
 */
export const branchStripMetrics = (
  orientation: SchematicOrientation,
  xProp?: number
): BranchStripMetrics => {
  const isHorizontal = orientation === "horizontal"
  const x = xProp ?? DIAGRAM_BASELINE[orientation]
  const nameFont = isHorizontal
    ? horizontalStationFontSize(x)
    : verticalStationFontSize(x)
  const labelLineHeight = BRANCH_STRIP_LABEL_LINE_HEIGHT
  const lineBox = nameFont * labelLineHeight

  const pitch = isHorizontal ? PITCH_EM.horizontal : PITCH_EM.vertical
  const mainPitch = nameFont * pitch.main
  const lanePitch = nameFont * pitch.lane
  const padding = nameFont * pitch.padding

  const strokeWidth = scale(x, LINE_DIAGRAM.lineThickness)
  const tickProtrude = scale(x, LINE_DIAGRAM.stationTick)
  const ringOuter = scale(x, LINE_DIAGRAM.interchange.outerDiameter / 2)
  const ringStroke = scale(x, LINE_DIAGRAM.interchange.stroke)
  const labelClearance = ringOuter + scale(x, 1.1)

  const verticalLabelWidth = Math.round(
    Math.min(
      isHorizontal
        ? nameFont * (16 / HORIZONTAL_NAME_SIZE_UNITS)
        : nameFont * PITCH_EM.vertical.labelWidth,
      lanePitch * 0.65
    )
  )

  const labelBand = Math.max(
    scale(x, LINE_DIAGRAM.layout.nameBelowLine) + lineBox,
    lineBox * 2
  )
  const labelBandTop = isHorizontal
    ? labelBand + labelClearance
    : lineBox * 2 + nameFont * 0.1 + labelClearance
  const labelBandBottom = isHorizontal
    ? labelBand + labelClearance
    : nameFont * (4 / VERTICAL_NAME_SIZE_UNITS)

  const labelSide = isHorizontal ? 0 : verticalLabelWidth + padding
  // Narrower than station pitch so neighbours on the same corridor don’t collide.
  const labelMaxWidth = Math.max(
    isHorizontal ? nameFont * 3.5 : nameFont * 2,
    mainPitch * 0.7
  )
  const endPad = isHorizontal ? labelMaxWidth / 2 + nameFont * 0.5 : 0
  const labelGap =
    ringOuter +
    nameFont * (isHorizontal ? 1.25 : 2.5 / VERTICAL_NAME_SIZE_UNITS)

  return {
    x,
    orientation,
    nameFont,
    labelLineHeight,
    lineBox,
    mainPitch,
    lanePitch,
    padding,
    verticalLabelWidth,
    labelClearance,
    labelMaxWidth,
    labelGap,
    labelBandTop,
    labelBandBottom,
    labelSideLeft: labelSide,
    labelSideRight: labelSide,
    endPad,
    strokeWidth,
    tickProtrude,
    ringOuter,
    ringStroke,
  }
}

export type BranchStripLabelSide =
  "above" | "below" | "left" | "right" | "stub-above"

export type BranchStripLabelPlacement = {
  id: string
  side: BranchStripLabelSide
  /** Estimated content box in layout coordinates (before SVG/label padding). */
  box: { x: number; y: number; w: number; h: number }
}

export type BranchStripLabelOptions = {
  orientation: SchematicOrientation
  nameFont: number
  labelMaxWidth: number
  verticalLabelWidth: number
  labelClearance: number
  labelGap: number
  /** Estimated lines of wrapped station text (1–2). */
  estimatedLines?: number
  /** Defaults to `BRANCH_STRIP_LABEL_LINE_HEIGHT`. */
  labelLineHeight?: number
}

const boxesOverlap = (
  a: { x: number; y: number; w: number; h: number },
  b: { x: number; y: number; w: number; h: number },
  pad = 0
): boolean =>
  a.x - pad < b.x + b.w &&
  a.x + a.w + pad > b.x &&
  a.y - pad < b.y + b.h &&
  a.y + a.h + pad > b.y

export const findOverlappingLabelPairs = (
  placements: readonly BranchStripLabelPlacement[],
  pad = 2
): Array<[string, string]> => {
  const pairs: Array<[string, string]> = []
  for (let i = 0; i < placements.length; i++) {
    for (let j = i + 1; j < placements.length; j++) {
      const a = placements[i]!
      const b = placements[j]!
      if (boxesOverlap(a.box, b.box, pad)) {
        pairs.push([a.id, b.id])
      }
    }
  }
  return pairs
}

/** Local rightmost lane labels right; others left — keeps CX clear of Bank. */
export const verticalLabelOnLeft = (
  point: SchematicLayoutPoint,
  layout: Pick<SchematicLayout, "points" | "minLane" | "maxLane">
): boolean => {
  const laneMid = (layout.minLane + layout.maxLane) / 2
  const nearby = layout.points.filter((p) => Math.abs(p.pos - point.pos) <= 1)
  const localMaxLane = Math.max(...nearby.map((p) => p.lane))
  const localMinLane = Math.min(...nearby.map((p) => p.lane))
  if (localMaxLane === localMinLane) {
    return point.lane <= laneMid
  }
  return point.lane < localMaxLane
}

/**
 * Place every station label. Cross-axis stubs (short arc spurs that still
 * read as mostly cross-track) sit above the stub tip.
 */
export const placeBranchStripLabels = (
  layout: SchematicLayout,
  options: BranchStripLabelOptions
): BranchStripLabelPlacement[] => {
  const {
    orientation,
    nameFont,
    labelMaxWidth,
    verticalLabelWidth,
    labelClearance,
    labelGap,
    estimatedLines = 2,
    labelLineHeight = BRANCH_STRIP_LABEL_LINE_HEIGHT,
  } = options
  const isHorizontal = orientation === "horizontal"
  const laneMid = (layout.minLane + layout.maxLane) / 2
  const textH = nameFont * labelLineHeight * estimatedLines

  return layout.points.map((point) => {
    if (isHorizontal) {
      const labelAbove = point.lane <= laneMid
      const w = labelMaxWidth
      const h = textH
      const x = point.x - w / 2
      const y = labelAbove
        ? point.y - labelClearance - h
        : point.y + labelClearance
      return {
        id: point.id,
        side: labelAbove ? "above" : "below",
        box: { x, y, w, h },
      }
    }

    // Vertical: spur tips with dominant cross-axis track → above.
    if (point.trackAxis === "x") {
      const w = verticalLabelWidth
      const h = textH
      return {
        id: point.id,
        side: "stub-above",
        box: {
          x: point.x - w / 2,
          y: point.y - labelClearance - h,
          w,
          h,
        },
      }
    }

    const onLeft = verticalLabelOnLeft(point, layout)
    const w = verticalLabelWidth
    const h = textH
    return {
      id: point.id,
      side: onLeft ? "left" : "right",
      box: {
        x: onLeft ? point.x - labelGap - w : point.x + labelGap,
        y: point.y - h / 2,
        w,
        h,
      },
    }
  })
}

import type { DiagramStation } from "@/lib/tfl/diagram-station"

/**
 * Presentational spine payload for LineStrip / demos.
 * Fetching (`getLineSpine`) stays in app loaders — not in this module.
 */
export type LineSpine = {
  lineId: string
  lineName: string
  lineColor: string
  stations: DiagramStation[]
  spineIds: string[]
  routeError?: string
}

/** Inclusive slice of a spine between two station ids (either order). */
export const sliceLineSpineStations = (
  stations: readonly DiagramStation[],
  fromId: string,
  toId: string
): DiagramStation[] => {
  const fromIndex = stations.findIndex((s) => s.id === fromId)
  const toIndex = stations.findIndex((s) => s.id === toId)
  if (fromIndex < 0 || toIndex < 0) return [...stations]
  const [start, end] =
    fromIndex <= toIndex ? [fromIndex, toIndex] : [toIndex, fromIndex]
  return stations.slice(start, end + 1)
}

import { formatStationName } from "@/lib/tfl/diagram-station"

/**
 * Lowercase + apostrophe fold for recipe / catalog lookup.
 * Apostrophes are stripped so "Queen's Park" and "Queens Park" share a key.
 */
export const stationLabelKey = (name: string): string =>
  name
    .toLowerCase()
    .replace(/[\u2018\u2019\u02BC']/g, "")
    .trim()

/**
 * Canonical station identity for diagrams, catalogs, and future multi-line maps.
 * Primary key is Naptan; aliases cover hub/child ID variants from TfL payloads.
 */
export type StationRecord = {
  id: string
  aliasIds: string[]
  name: string
  displayName: string
  lineIds: string[]
  modeIds: string[]
}

/**
 * Visual packing recipe for a station label on crowded diagrams.
 * Prefer `stationId`; `nameKey` is the fallback for demos / missing IDs.
 */
export type StationLabelRecipe = {
  stationId?: string
  /** Extra Naptans that share this recipe (homonyms on different lines). */
  stationIds?: readonly string[]
  /** Normalised display-name key from `stationLabelKey`. */
  nameKey?: string
  lines: readonly string[]
  abbreviated?: boolean
}

export type StationIndex = {
  byId: ReadonlyMap<string, StationRecord>
  /** displayName key → primary id (first seen). */
  byDisplayKey: ReadonlyMap<string, string>
}

export const emptyStationIndex = (): StationIndex => ({
  byId: new Map(),
  byDisplayKey: new Map(),
})

/**
 * Merge a stop into an accumulating index keyed by Naptan.
 * Same display name with a different ID becomes an alias on the first record
 * when `mergeHomonyms` is true; otherwise a separate record is kept.
 * For serving lines and arrivals fetch targets use `STATION_HUBS` via
 * `station-catalog.ts`, not this name merge.
 */
export const upsertStationRecord = (
  index: {
    byId: Map<string, StationRecord>
    byDisplayKey: Map<string, string>
  },
  input: {
    id: string
    name: string
    lineId?: string
    modeId?: string
    aliasIds?: string[]
  },
  options: { mergeHomonyms?: boolean } = {}
): void => {
  const { mergeHomonyms = true } = options
  const id = input.id.trim()
  if (!id) return

  const displayName = formatStationName(input.name)
  const displayKey = stationLabelKey(displayName)
  const existingById = index.byId.get(id)

  if (existingById) {
    if (input.lineId)
      existingById.lineIds = uniqPush(existingById.lineIds, input.lineId)
    if (input.modeId)
      existingById.modeIds = uniqPush(existingById.modeIds, input.modeId)
    for (const alias of input.aliasIds ?? []) {
      existingById.aliasIds = uniqPush(existingById.aliasIds, alias)
      index.byId.set(alias, existingById)
    }
    return
  }

  const primaryForName = index.byDisplayKey.get(displayKey)
  if (mergeHomonyms && primaryForName) {
    const primary = index.byId.get(primaryForName)
    if (primary) {
      primary.aliasIds = uniqPush(primary.aliasIds, id)
      index.byId.set(id, primary)
      if (input.lineId)
        primary.lineIds = uniqPush(primary.lineIds, input.lineId)
      if (input.modeId)
        primary.modeIds = uniqPush(primary.modeIds, input.modeId)
      return
    }
  }

  const record: StationRecord = {
    id,
    aliasIds: [...new Set((input.aliasIds ?? []).filter(Boolean))],
    name: input.name,
    displayName,
    lineIds: input.lineId ? [input.lineId] : [],
    modeIds: input.modeId ? [input.modeId] : [],
  }
  index.byId.set(id, record)
  for (const alias of record.aliasIds) {
    index.byId.set(alias, record)
  }
  if (!index.byDisplayKey.has(displayKey)) {
    index.byDisplayKey.set(displayKey, id)
  }
}

export const resolveStationRecord = (
  index: StationIndex,
  idOrName: string
): StationRecord | undefined => {
  const byId = index.byId.get(idOrName)
  if (byId) return byId
  const key = stationLabelKey(formatStationName(idOrName))
  const primary = index.byDisplayKey.get(key)
  return primary ? index.byId.get(primary) : undefined
}

/** IDs that should match the same physical stop in disruption payloads. */
export const stationRecordIdentityIds = (record: StationRecord): string[] => [
  ...new Set([record.id, ...record.aliasIds]),
]

const uniqPush = (list: string[], value: string): string[] =>
  list.includes(value) ? list : [...list, value]

